/* Generated by scripts/build.js from scripts/guide.js. Do not edit by hand. */
window.RainlineGuideData = {"crops":{"peas":{"difficulty":1,"sun":"Full sun; tolerates light shade","spacing":"2 inches apart along a trellis","depth":"1 inch deep","harvest":"Pick snap and snow peas when pods are plump but still crisp, every two or three days.","problem":"Birds and slugs go after young shoots. Cover rows with netting until plants are a few inches tall.","varieties":["Oregon Sugar Pod II","Sugar Snap","Green Arrow"]},"radishes":{"difficulty":1,"sun":"Full sun; tolerates light shade","spacing":"1 inch apart (thin to 2 inches)","depth":"½ inch deep","harvest":"Most are ready in about four weeks. Pull them while they're small; they turn woody if left too long.","problem":"Cabbage root maggots tunnel into roots in cool, wet springs. Row cover laid on at sowing keeps the flies off.","varieties":["Cherry Belle","French Breakfast","Easter Egg"]},"spinach":{"difficulty":2,"sun":"Full sun to part shade","spacing":"3 inches apart","depth":"½ inch deep","harvest":"Cut outer leaves once plants have five or six, or cut the whole plant before it sends up a flower stalk.","problem":"Bolts (goes to seed) as days lengthen in late spring. Sow early, and sow again in late summer for fall and winter.","varieties":["Bloomsdale Long Standing","Space","Giant Winter (for fall sowing)"]},"lettuce":{"difficulty":1,"sun":"Full sun in spring; afternoon shade in summer","spacing":"8 to 10 inches apart for heads","depth":"¼ inch deep (it needs light to sprout)","harvest":"Pick outer leaves as needed, or cut whole heads when full. Harvest in the morning for the crispest leaves.","problem":"Slugs are the Northwest lettuce pest. Iron phosphate slug bait is safe around pets and edible crops.","varieties":["Buttercrunch","Black Seeded Simpson","Winter Density"]},"onions":{"difficulty":2,"sun":"Full sun","spacing":"4 inches apart","depth":"Sets 1 inch deep with the tip just showing; starts at the depth they grew","harvest":"When the tops flop over in late summer, pull the onions and let them dry in a shady, airy spot for two weeks.","problem":"Weeds outcompete onions' thin leaves. Keep the bed weeded and mulched.","varieties":["Walla Walla Sweet","Copra (stores well)","Redwing"]},"carrots":{"difficulty":2,"sun":"Full sun","spacing":"Thin to 2 inches apart","depth":"¼ inch deep","harvest":"Pull when the shoulders are about ¾ inch across. Fall carrots sweeten after a light frost.","problem":"Carrot rust fly larvae tunnel through roots. Cover the bed with insect netting from sowing on.","varieties":["Scarlet Nantes","Bolero","Danvers"]},"beets":{"difficulty":2,"sun":"Full sun; tolerates light shade","spacing":"Thin to 3 inches apart","depth":"½ inch deep","harvest":"Pull at golf ball to tennis ball size. The greens are edible too.","problem":"Leaf miners leave pale trails in the leaves. Pick off affected leaves and use row cover.","varieties":["Detroit Dark Red","Chioggia","Early Wonder"]},"kale":{"difficulty":1,"sun":"Full sun to part shade","spacing":"18 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Pick the lower leaves and let the top keep growing. Plants often produce from fall through spring west of the Cascades.","problem":"Cabbage worms and aphids. Row cover keeps the white cabbage moths from laying eggs.","varieties":["Lacinato","Red Russian","Winterbor"]},"broccoli":{"difficulty":2,"sun":"Full sun","spacing":"18 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Cut the main head while the buds are tight and dark green. Side shoots follow for weeks.","problem":"Cabbage worms and aphids. Cover young plants with insect netting.","varieties":["Packman","Green Magic","Purple Sprouting (overwinters west of the Cascades)"]},"cabbage":{"difficulty":2,"sun":"Full sun","spacing":"18 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Cut when heads feel firm when squeezed. Water evenly to keep heads from splitting.","problem":"Cabbage worms and root maggots. Row cover from planting day prevents both.","varieties":["Golden Acre","Early Jersey Wakefield","January King (winter)"]},"chard":{"difficulty":1,"sun":"Full sun to part shade","spacing":"10 inches apart","depth":"½ inch deep","harvest":"Cut outer stalks at the base. One planting keeps producing from early summer into winter.","problem":"Leaf miners, the same as beets. Remove spotted leaves early.","varieties":["Bright Lights","Fordhook Giant","Rhubarb"]},"potatoes":{"difficulty":1,"sun":"Full sun","spacing":"12 inches apart in rows 30 inches apart","depth":"4 inches deep in a trench","harvest":"Dig new potatoes when the plants flower. For storage potatoes, wait two weeks after the tops die back.","problem":"Wireworms in beds that were recently lawn. Grow potatoes in an established bed if you can.","varieties":["Yukon Gold","German Butterball","Red Norland"]},"beans":{"difficulty":1,"sun":"Full sun","spacing":"3 inches apart","depth":"1 inch deep","harvest":"Pick when pods are pencil-thick and before the seeds bulge. Picking often keeps plants producing.","problem":"Seeds rot in cold, wet soil, the most common Northwest bean failure. Wait for warm soil.","varieties":["Provider (sprouts in cooler soil)","Blue Lake 274","Royal Burgundy"]},"corn":{"difficulty":2,"sun":"Full sun","spacing":"10 inches apart in a block of short rows","depth":"1 inch deep","harvest":"Ready about three weeks after the silks appear, when the silks are brown and the kernels squirt milky juice.","problem":"Crows pull up sprouting seeds. Cover the bed with netting or row cover until plants are 4 inches tall.","varieties":["Early Sunglow","Bodacious","Golden Bantam"]},"cucumbers":{"difficulty":2,"sun":"Full sun","spacing":"12 inches apart on a trellis","depth":"1 inch deep","harvest":"Pick slicers at 6 to 8 inches, before they yellow. Check plants every day or two in midsummer.","problem":"Powdery mildew in late summer. Grow them up a trellis for airflow and water at the base.","varieties":["Marketmore 76","Lemon","Diva"]},"summer-squash":{"difficulty":1,"sun":"Full sun","spacing":"3 feet apart","depth":"1 inch deep","harvest":"Pick zucchini at 6 to 8 inches. Miss a few days and you'll have a baseball bat.","problem":"Powdery mildew late in the season. Remove the worst leaves and keep watering at the base.","varieties":["Black Beauty","Costata Romanesco","Early Prolific Straightneck"]},"winter-squash":{"difficulty":2,"sun":"Full sun","spacing":"4 feet apart (vines spread)","depth":"1 inch deep","harvest":"Cut when the rind resists a fingernail and the stem is dry, before a hard frost. Cure in a warm room for two weeks.","problem":"A short or cool season. Delicata and other fast varieties ripen far more reliably here than big pumpkins.","varieties":["Delicata","Sugar Pie pumpkin","Sweet Meat (an Oregon heirloom)"]},"tomatoes":{"difficulty":2,"sun":"Full sun; the hottest spot you have","spacing":"2 feet apart","depth":"Bury the stem up to the first leaves","harvest":"Pick when fully colored. Before fall rains, pick green tomatoes and ripen them indoors.","problem":"Late blight in wet falls turns leaves and fruit brown. Keep leaves dry and give plants space.","varieties":["Stupice","Early Girl","Sungold (cherry)","Oregon Spring (bred in Oregon)"]},"peppers":{"difficulty":3,"sun":"Full sun; against a warm wall if possible","spacing":"18 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Pick green any time once full size, or leave them to ripen red, which can take three more weeks.","problem":"Cool nights stall growth. Black plastic mulch and row cover early in the season make a big difference here.","varieties":["Gypsy","Ace","Early Jalapeño","Lunchbox snacking peppers"]},"basil":{"difficulty":2,"sun":"Full sun","spacing":"12 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Pinch off the top pair of leaves often so plants bush out, and remove flower buds.","problem":"Cold. Nights below about 50°F blacken and stunt basil, so it goes out last and comes in at the first chilly night.","varieties":["Genovese","Thai","Spicy Globe"]},"dahlias":{"difficulty":2,"sun":"Full sun","spacing":"18 to 24 inches apart","depth":"4 to 6 inches deep, eye pointing up","plantText":"dahlia tubers","firstHarvest":"Blooms from midsummer until the first frost","harvest":"Cut flowers when they're almost fully open, early in the morning. The more you cut, the more they bloom.","problem":"Slugs and earwigs chew young shoots and petals. Use iron phosphate slug bait early in the season.","varieties":["Café au Lait","Bishop of Llandaff","Cornel Brons"],"care":"Don't water tubers until shoots appear, then water deeply once a week. Stake tall varieties when you plant so you don't spear the tuber later."},"cilantro":{"difficulty":1,"sun":"Full sun; afternoon shade in summer","spacing":"4 inches apart","depth":"¼ inch deep","harvest":"Cut leaves once plants are about 6 inches tall. If it bolts, let it go to seed and harvest the coriander.","problem":"Bolting in warm weather. Look for slow-bolt varieties and sow little and often.","varieties":["Calypso (slow to bolt)","Santo","Leisure"]},"parsley":{"difficulty":1,"sun":"Full sun to part shade","spacing":"8 inches apart","depth":"¼ inch deep","harvest":"Cut outer stems at the base and let the center keep growing.","problem":"Slow, patchy sprouting. Soak seeds overnight before sowing, or buy young plants.","varieties":["Italian Flat Leaf","Moss Curled","Giant of Italy"]},"dill":{"difficulty":1,"sun":"Full sun","spacing":"12 inches apart","depth":"¼ inch deep","harvest":"Snip leaves any time. For pickling, cut the flower heads just as they open.","problem":"Tall plants flop in wind and rain. Grow 'Fernleaf', a compact variety, or give it a stake.","varieties":["Fernleaf (compact)","Bouquet","Mammoth"]},"strawberries":{"difficulty":1,"sun":"Full sun","spacing":"12 to 18 inches apart","depth":"Crown at soil level: not buried, roots covered","plantText":"strawberry plants","firstHarvest":"A light crop the first summer; full crops from the second year","harvest":"Pick fully red berries every couple of days, in the morning, with the cap attached.","problem":"Gray mold (botrytis) in wet springs and slugs on ripe berries. Mulch with straw to keep fruit off the soil.","varieties":["Hood (an Oregon classic)","Shuksan","Seascape (everbearing)","Albion (day-neutral)"],"care":"Water regularly, mulch with straw, and pinch off runners in the first year so plants put energy into roots."},"blueberries":{"difficulty":1,"sun":"Full sun","spacing":"4 to 5 feet apart","depth":"Same depth as in the pot","plantText":"blueberry bushes","firstHarvest":"Small crops in year two or three; full crops by year five","harvest":"Pick berries a few days after they turn fully blue, when they roll off into your hand.","problem":"Birds. Cover bushes with netting as berries color, or plant extra.","varieties":["Duke (early)","Chandler (huge berries)","Bluecrop","Top Hat (for containers)"],"care":"Mix peat moss or acidic compost into the planting hole, mulch with sawdust or bark, and pinch off flowers the first year."},"raspberries":{"difficulty":2,"sun":"Full sun","spacing":"2 to 3 feet apart in rows","depth":"Roots covered by 2 to 3 inches of soil","plantText":"raspberry canes","firstHarvest":"Light crop in year two (fall-bearers can fruit the first fall)","harvest":"Pick when berries slip easily off the core. Check every two or three days in season.","problem":"Root rot in soggy soil. Plant in a raised row or a bed that drains well.","varieties":["Meeker (a Northwest favorite)","Tulameen","Heritage (fall-bearing)","Cascade Delight"],"care":"Set up a simple trellis with posts and wire. After harvest, cut spent canes to the ground."},"garlic":{"difficulty":1,"sun":"Full sun","spacing":"6 inches apart","depth":"2 inches deep, pointed end up","harvest":"Dig in early summer when the lower third of the leaves are brown. Cure in a shady, airy spot for three weeks.","problem":"Rust (orange spots on leaves) in wet springs. It's mostly cosmetic; give plants space and pull weeds.","varieties":["Music (hardneck)","Inchelium Red (softneck, from Washington)","Chesnok Red"]},"cauliflower":{"difficulty":3,"sun":"Full sun","spacing":"18 to 24 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Cut the head while it's firm and tight, before the curds start to separate. Tie the outer leaves over young heads to keep them white.","problem":"A cold snap or dry spell makes plants form tiny 'button' heads. Keep the soil evenly moist and don't rush spring planting.","varieties":["Snow Crown","Amazing","Graffiti (purple)"]},"brussels-sprouts":{"difficulty":2,"sun":"Full sun","spacing":"24 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Pick sprouts from the bottom of the stalk up once they're firm and about an inch across. Frost improves the flavor.","problem":"Aphids cluster on the sprouts in late summer. Knock them off with a strong spray of water every few days.","varieties":["Long Island Improved","Diablo","Churchill"]},"leeks":{"difficulty":1,"sun":"Full sun","spacing":"6 inches apart","depth":"Set seedlings in a hole about 6 inches deep so the stems grow long and white","harvest":"Dig whenever stems are an inch or more across. West of the Cascades you can leave them in the ground and harvest all winter.","problem":"Weeds crowd young leeks. Mulch and weed regularly while the plants are small.","varieties":["King Richard (early)","Bandit (winter-hardy)","American Flag"]},"arugula":{"difficulty":1,"sun":"Full sun to part shade","spacing":"Thin to 4 inches apart","depth":"¼ inch deep","harvest":"Pick leaves when they're 2 to 3 inches long, about three weeks after sowing. Young leaves are the mildest.","problem":"Flea beetles riddle the leaves with tiny holes in spring. Floating row cover laid on at sowing keeps them off.","varieties":["Astro","Wild arugula (Sylvetta)","Rocket"]},"bok-choy":{"difficulty":1,"sun":"Full sun to part shade","spacing":"6 to 10 inches apart","depth":"¼ inch deep","harvest":"Cut baby bok choy at about 6 inches tall, or whole heads at full size. Harvest before a flower stalk appears.","problem":"Flea beetles and slugs chew the leaves. Row cover and iron phosphate slug bait handle both.","varieties":["Joi Choi","Toy Choy (baby size)","Mei Qing Choi"]},"turnips":{"difficulty":1,"sun":"Full sun","spacing":"Thin to 4 inches apart","depth":"½ inch deep","harvest":"Pull at 2 to 3 inches across for tender roots. The greens are good to eat too.","problem":"Cabbage root maggots tunnel into roots in cool, wet soil. Cover the bed with row cover from sowing on.","varieties":["Hakurei (salad turnip)","Purple Top White Globe","Scarlet Queen"]},"kohlrabi":{"difficulty":1,"sun":"Full sun","spacing":"Thin to 6 inches apart","depth":"¼ to ½ inch deep","harvest":"Cut bulbs at 2 to 3 inches across. Peel off the tough skin and eat raw or cooked.","problem":"Cabbage worms chew the leaves. Insect netting keeps the white moths from laying eggs.","varieties":["Kolibri (purple)","Winner","Kossak (large, stores well)"]},"eggplant":{"difficulty":3,"sun":"Full sun; the hottest spot you have","spacing":"18 to 24 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Pick when the skin is glossy and springs back when pressed. Dull skin means it's overripe and seedy.","problem":"Flea beetles riddle young leaves, and cool nights stall growth. Keep row cover on until plants are growing strongly.","varieties":["Hansel (early, small fruit)","Fairy Tale","Orient Express"]},"melons":{"difficulty":3,"sun":"Full sun; the hottest spot you have","spacing":"24 to 36 inches apart","depth":"1 inch deep","harvest":"Cantaloupes are ripe when the stem slips off with a gentle push. Watermelons are ready when the curly tendril nearest the fruit turns brown and dry.","problem":"Cool soil and cool nights are the main obstacle west of the Cascades. Black plastic mulch and row cover until flowering make the difference.","varieties":["Sugar Baby (watermelon)","Minnesota Midget (cantaloupe)","Halona (cantaloupe)"]},"pole-beans":{"difficulty":1,"sun":"Full sun","spacing":"4 to 6 inches apart along a trellis","depth":"1 inch deep","harvest":"Pick when pods are pencil-thick and before the seeds bulge. Picking every few days keeps the vines producing.","problem":"Seeds rot in cold, wet soil, the most common Northwest bean failure. Wait for warm soil.","varieties":["Blue Lake FM-1K","Kentucky Wonder","Fortex"]},"fava-beans":{"difficulty":1,"sun":"Full sun","spacing":"6 inches apart","depth":"1 to 2 inches deep","harvest":"Pick pods when they bulge with beans but are still green. Shell the beans and slip off the pale skins for the sweetest flavor.","problem":"Black aphids gather on the growing tips in late spring. Pinch off the tips once pods start forming.","varieties":["Broad Windsor","Aquadulce Claudia (for fall sowing)","Vroma"]},"shallots":{"difficulty":1,"sun":"Full sun","spacing":"6 to 8 inches apart","depth":"Tip just at the soil surface","harvest":"Dig in summer when the tops yellow and fall over. Dry the clusters in a shady, airy spot for two weeks.","problem":"Onion maggots in cool, wet soil. Plant onion-family crops in a different spot each year.","varieties":["French Gray (gourmet, very hardy)","Ambition","Dutch Yellow"]},"asparagus":{"difficulty":2,"sun":"Full sun","spacing":"12 to 18 inches apart","depth":"In a trench 6 to 8 inches deep, covered gradually as the spears grow","plantText":"asparagus crowns","firstHarvest":"Light picking in year two; full harvests from year three","harvest":"Snap spears at soil level when they're 6 to 8 inches tall. Stop picking when new spears are pencil-thin, and let the ferns grow.","problem":"Asparagus beetles chew the spears and ferns. Hand-pick them in the morning.","varieties":["Jersey Knight","Millennium","Purple Passion"],"care":"Fill the trench in gradually as the shoots grow. Keep the bed weeded, and cut the ferns down only after they turn brown in fall."},"rhubarb":{"difficulty":1,"sun":"Full sun to part shade","spacing":"3 to 4 feet apart","depth":"Crown buds 1 to 2 inches below the surface","plantText":"rhubarb crowns","firstHarvest":"Light picking in year two; full harvests from year three","harvest":"Pull (don't cut) stalks when they're 10 to 15 inches long. Take no more than a third at once, and stop in early summer. Never eat the leaves.","problem":"Crown rot in soggy soil. In wet west-side gardens, plant on a slight mound or in a raised bed.","varieties":["Victoria","Canada Red","Crimson Red"],"care":"Mulch with compost each spring, and cut off flower stalks as soon as they appear."},"chives":{"difficulty":1,"sun":"Full sun to part shade","spacing":"8 to 12 inches apart","depth":"¼ inch deep","harvest":"Snip leaves an inch above the soil whenever you need them. The purple flowers are edible too.","problem":"Few pests. Clumps get crowded after a few years; dig and divide them in spring.","varieties":["Common chives","Garlic chives","Staro"]},"mint":{"difficulty":1,"sun":"Full sun to part shade","spacing":"One plant per pot, or 18 inches apart","depth":"Plant at the depth it grew in the nursery pot","plantText":"young mint plants","firstHarvest":"Pick lightly the first summer, then as much as you like","harvest":"Snip stems just above a pair of leaves. Regular cutting keeps plants bushy.","problem":"Mint spreads underground and takes over beds. Grow it in a container.","varieties":["Spearmint","Peppermint","Mojito mint"],"care":"Water regularly; mint likes moist soil. Cut it back hard in midsummer for a fresh flush of leaves."},"rosemary":{"difficulty":2,"sun":"Full sun","spacing":"24 to 36 inches apart","depth":"Plant at the depth it grew in the nursery pot","plantText":"young rosemary plants","firstHarvest":"Pick sprigs a few weeks after planting, once new growth appears","harvest":"Snip sprig tips as needed. Don't cut back into bare wood; it won't regrow.","problem":"Wet winter soil kills more rosemary than cold does. Plant in fast-draining soil or a raised bed.","varieties":["Arp (selected for cold hardiness)","Hill Hardy","Tuscan Blue"],"care":"Water until established, then only in dry spells. In cold eastern areas, grow it in a pot and move it to a cool, bright spot for winter.","frost":"Handles light frost; wet winter soil is the bigger risk"},"thyme":{"difficulty":1,"sun":"Full sun","spacing":"12 inches apart","depth":"Plant at the depth it grew in the nursery pot","plantText":"young thyme plants","firstHarvest":"Pick lightly the first year, freely after that","harvest":"Snip sprigs before the plant flowers for the best flavor. Trim lightly after flowering to keep it compact.","problem":"Root rot in heavy, wet soil. Give it gravelly soil or a raised spot.","varieties":["English thyme","French thyme","Lemon thyme"],"care":"Water only until established; thyme prefers dry soil. Replace plants every few years when they get woody."},"oregano":{"difficulty":1,"sun":"Full sun","spacing":"12 to 18 inches apart","depth":"Plant at the depth it grew in the nursery pot","plantText":"young oregano plants","firstHarvest":"Pick lightly the first year, freely after that","harvest":"Cut stems just before flowering, when flavor peaks. Dry bunches upside down in a shady, airy spot.","problem":"Few pests. Plants sprawl and get woody; cut them back by half in early summer.","varieties":["Greek oregano (strongest flavor)","Italian oregano","Golden oregano"],"care":"Water sparingly once established. Rich soil makes the flavor milder, so skip the fertilizer."},"sunflowers":{"difficulty":1,"sun":"Full sun","spacing":"6 inches (small types) to 24 inches (giants) apart","depth":"1 inch deep","firstHarvest":"Blooms about 60 to 90 days after sowing","harvest":"Cut flowers when the petals are just opening. For seeds, let heads dry on the plant until the back turns brown, and cover them from birds.","problem":"Birds and slugs eat seedlings. Cover the seedbed until plants are a few inches tall.","varieties":["Mammoth Grey Stripe (giant)","ProCut (for cutting)","Teddy Bear (dwarf)"]},"sweet-peas":{"difficulty":2,"sun":"Full sun","spacing":"4 to 6 inches apart along a trellis","depth":"1 inch deep (soak seeds overnight first)","firstHarvest":"Blooms in early summer","harvest":"Cut stems every couple of days; the more you pick, the more they bloom. Plants stop flowering once pods form.","problem":"Aphids and powdery mildew late in the season. Sow early so plants peak before summer heat.","varieties":["Cupani (very fragrant)","Spencer mix","Royal Family (more heat-tolerant)"]},"tulips":{"difficulty":1,"sun":"Full sun","spacing":"4 to 6 inches apart","depth":"6 to 8 inches deep, pointed end up","firstHarvest":"Blooms in April and May","harvest":"Cut when buds show color but are still closed. After blooming, let the leaves die back on their own to feed the bulb.","problem":"Squirrels, voles and deer eat tulips. Plant bulbs in wire cages, or choose daffodils where animals are a problem.","varieties":["Darwin hybrids (return best)","Apeldoorn","Queen of Night"],"frost":"Fully hardy; needs winter cold to bloom"},"daffodils":{"difficulty":1,"sun":"Full sun to part shade","spacing":"4 to 6 inches apart","depth":"6 inches deep, pointed end up","firstHarvest":"Blooms from late winter to spring, depending on variety","harvest":"Cut when buds are just opening. Their sap harms other flowers in a vase, so stand them alone for a few hours first. Let the leaves die back on their own.","problem":"Bulbs rot in soggy soil. Plant on a slope or in well-drained beds.","varieties":["Tête-à-Tête (early, small)","Dutch Master","Thalia (white)"],"frost":"Fully hardy; needs winter cold to bloom"},"apples":{"difficulty":2,"sun":"Full sun","spacing":"8 to 12 feet apart for dwarf trees, 15 to 20 feet for semi-dwarf","depth":"Graft union 2 to 3 inches above the soil","plantText":"apple trees","firstHarvest":"First apples in two to four years on dwarf trees, longer on bigger ones","harvest":"Apples are ripe when the seeds turn brown and the fruit comes off with a gentle lift and twist. Taste one before picking the tree.","problem":"Apple scab (dark, scabby spots on leaves and fruit) in wet springs, and codling moth worms in the fruit. Plant a scab-resistant variety and rake up fallen leaves in fall.","varieties":["Liberty (scab-resistant)","Akane (early)","Honeycrisp","Gravenstein"],"care":"Water deeply every week or two through the first two summers. Prune in late winter to an open shape, and thin young fruit to one per cluster in June for bigger apples."},"pears":{"difficulty":1,"sun":"Full sun","spacing":"12 to 15 feet apart for dwarf trees, 18 to 20 feet for standard","depth":"Graft union 2 to 3 inches above the soil","plantText":"pear trees","firstHarvest":"First pears in three to five years","harvest":"Pick European pears when they're full size and lift off easily but are still hard, then ripen them at room temperature. Asian pears ripen on the tree; pick when sweet and crisp.","problem":"Pear scab in wet springs and fire blight in warm, humid bloom weather (more common east of the Cascades). Cut out blackened, shepherd's-crook shoots well below the damage.","varieties":["Bartlett","Comice","Seckel (small, very sweet)","Shinseiki (Asian)"],"care":"Water deeply through the first two summers. Pears need little pruning; take out crossing branches in late winter and keep the center open."},"plums":{"difficulty":1,"sun":"Full sun","spacing":"12 to 15 feet apart for dwarf or semi-dwarf trees","depth":"Graft union 2 to 3 inches above the soil","plantText":"plum trees","firstHarvest":"First plums in three to five years","harvest":"Pick when the fruit is fully colored, slightly soft and comes off easily. Prune plums for drying should hang until they wrinkle slightly at the stem.","problem":"Brown rot turns ripening fruit into fuzzy, gray mummies in wet weather. Thin fruit so plums don't touch, and pick off any mummies.","varieties":["Italian prune","Stanley","Methley (Japanese)","Shiro (Japanese)"],"care":"Water deeply through the first two summers. Prune lightly in summer, not winter, which lowers the risk of silver leaf and canker. Thin heavy crops so branches don't snap."},"cherries":{"difficulty":3,"sun":"Full sun","spacing":"15 to 20 feet apart (8 to 10 feet on dwarf rootstock)","depth":"Graft union 2 to 3 inches above the soil","plantText":"cherry trees","firstHarvest":"First cherries in three to five years","harvest":"Pick sweet cherries when they're fully colored and taste sweet; they don't ripen after picking. Keep the stems on for longer storage.","problem":"Birds, and fruit that cracks when it rains near harvest. Net small trees, and pick crack-resistant varieties west of the Cascades. Bacterial canker oozes gum from branches in wet springs.","varieties":["Lapins (self-fertile, crack-resistant)","Stella (self-fertile)","Rainier (needs a partner)","Montmorency (sour)"],"care":"Choose a dwarfing rootstock like Gisela so you can net the tree. Water deeply through the first two summers, and prune in summer during dry weather to reduce canker."},"figs":{"difficulty":2,"sun":"Full sun; against a warm south or west wall","spacing":"10 to 15 feet apart","depth":"Same depth as in the pot, or a little deeper","plantText":"fig trees","firstHarvest":"Often a few figs in the first two years","harvest":"Figs don't ripen after picking. Wait until they droop on the stem, feel soft and the skin starts to crack slightly.","problem":"Hard freezes kill young trees back to the ground, and unripe figs from late summer won't finish in a cool fall. Pick early-ripening varieties and protect young trees in cold snaps.","varieties":["Desert King (reliable breba crop)","Lattarula","Brown Turkey","Chicago Hardy"],"care":"Water deeply through the first summer. Mulch the base heavily in fall, and wrap young trees in frost cloth when temperatures drop toward the teens.","frost":"Hardy to about 10 to 15°F once established; young trees need protection"},"peaches":{"difficulty":3,"sun":"Full sun; the hottest spot you have","spacing":"12 to 15 feet apart (8 to 10 for dwarf)","depth":"Graft union 2 to 3 inches above the soil","plantText":"peach trees","firstHarvest":"First peaches in two to four years","harvest":"Pick when the green background color turns fully yellow and the fruit gives slightly to gentle pressure.","problem":"Peach leaf curl: red, puckered leaves in spring, caused by a fungus that infects buds in wet late winter weather. Plant a resistant variety, or keep spring rain off the tree with an overhang or cover.","varieties":["Frost (curl-resistant)","Q-1-8 (curl-resistant)","Charlotte (curl-resistant)","Redhaven (east of the Cascades)"],"care":"Peaches fruit on last year's growth, so prune every late winter to keep new wood coming. Thin young fruit to 6 to 8 inches apart for good-sized peaches."},"hazelnuts":{"difficulty":1,"sun":"Full sun","spacing":"15 to 20 feet apart","depth":"Same depth as in the nursery","plantText":"hazelnut trees","firstHarvest":"First nuts in three to five years","harvest":"Nuts drop on their own from late August to October. Rake them up every few days, before squirrels and jays do, and dry them for a couple of weeks.","problem":"Eastern filbert blight, which girdles branches with rows of black, football-shaped cankers. Plant blight-resistant varieties.","varieties":["Jefferson (blight-resistant)","Yamhill (blight-resistant)","Theta (pollinizer)","McDonald (blight-resistant)"],"care":"Plant at least two compatible varieties for pollination. Water through the first two summers, and pull suckers from the base each year if you want a tree rather than a bush."},"blackberries":{"difficulty":1,"sun":"Full sun","spacing":"3 to 5 feet apart for upright types, 5 to 8 feet for trailing","depth":"Same depth as in the pot, roots covered","plantText":"blackberry canes","firstHarvest":"A light crop in year two, full crops from year three","harvest":"Pick when berries turn from shiny to slightly dull black and pull off easily. Check every two or three days in season.","problem":"Spotted wing drosophila, a small fruit fly whose larvae turn ripe berries mushy. Pick often, pick everything ripe and chill berries right away.","varieties":["Marion (trailing, thorny)","Black Diamond (thornless trailing)","Triple Crown (thornless semi-erect)","Chester (cold-hardy thornless)"],"care":"Train canes on a two-wire trellis. Canes fruit in their second year; after harvest, cut the canes that fruited to the ground and tie up the new ones."},"grapes":{"difficulty":2,"sun":"Full sun; a warm south-facing spot","spacing":"6 to 8 feet apart along a trellis","depth":"Same depth as in the pot","plantText":"grape vines","firstHarvest":"First bunches in year three","harvest":"Taste before picking: grapes don't sweeten after harvest. Seeds turn brown and stems start to turn woody when they're ripe.","problem":"Powdery mildew, a white coating on leaves and fruit. Choose resistant varieties, prune for airflow and pull a few leaves around the bunches in early summer.","varieties":["Interlaken (seedless, early)","Himrod (seedless)","Canadice (seedless, red)","Concord (east of the Cascades)"],"care":"Build a trellis or arbor before planting. Prune hard every winter, removing most of last year's growth; grapes fruit on new shoots from one-year-old wood."},"hardy-kiwi":{"difficulty":2,"sun":"Full sun to light shade","spacing":"10 to 15 feet apart","depth":"Same depth as in the pot","plantText":"hardy kiwi vines","firstHarvest":"First fruit in three to five years","harvest":"Pick in September when a few fruits soften on the vine, then ripen the firm ones at room temperature or store them in the fridge for weeks.","problem":"Late spring frost kills tender new shoots and that year's flowers. Plant away from cold low spots, and cover young vines on frosty spring nights.","varieties":["Ananasnaya (female)","Ken's Red (female)","Issai (self-fertile)","Meader (male)"],"care":"Plant one male for up to eight females unless you grow Issai. Build a strong arbor or T-bar trellis. Prune hard in winter and again lightly in summer to tame the vines."},"artichokes":{"difficulty":2,"sun":"Full sun","spacing":"3 to 4 feet apart","depth":"Plant starts at the depth they grew in the pot","plantText":"artichoke plants","firstHarvest":"Buds in late summer the first year from Imperial Star; otherwise from early summer of year two","harvest":"Cut buds with an inch or two of stem while the scales are still tight. Smaller side buds follow the big central one.","problem":"Wet, cold winters rot the crowns. Plant in soil that drains well, and in fall cut plants down and cover the crowns with a thick layer of straw or leaves.","varieties":["Imperial Star (best as an annual)","Green Globe","Violetto"],"care":"Water deeply and feed with compost; artichokes are big, hungry plants. Mulch to keep roots cool in summer and the crowns dry in winter.","frost":"Crowns survive about 15°F under thick mulch"},"huckleberries":{"difficulty":2,"sun":"Part shade to full sun","spacing":"3 to 5 feet apart","depth":"Same depth as in the pot","plantText":"evergreen huckleberry shrubs","firstHarvest":"Light crops after two to three years; plants are slow to start","harvest":"Pick evergreen huckleberries from late August into fall, when they're fully dark and come off easily. They hang on the shrub for weeks.","problem":"Slow growth in heavy or alkaline soil. Huckleberries want acidic, well-drained, organic soil, like a forest floor.","varieties":["Evergreen huckleberry (Vaccinium ovatum)","Red huckleberry (Vaccinium parvifolium)","Thunderbird (compact evergreen selection)"],"care":"Mulch with bark or fir needles, water through the first two dry seasons, and feed lightly with a fertilizer for acid-loving plants. No pruning needed beyond shaping."},"oregon-grape":{"difficulty":1,"sun":"Full sun to full shade","spacing":"3 to 5 feet apart","depth":"Same depth as in the pot","plantText":"Oregon grape shrubs","firstHarvest":"Flowers and berries from the second or third year","harvest":"Pick the dusty-blue berries in late summer. They're very tart and seedy; cook them into jelly with sugar, or leave them for the birds.","problem":"Few problems. Leaf spot and rust can show up in wet, crowded spots; give plants some airflow.","varieties":["Tall Oregon grape (Mahonia aquifolium)","Low Oregon grape (Mahonia nervosa, for shade)","Compacta (shorter)"],"care":"Water through the first summer, then leave it alone. Cut a few of the oldest stems to the ground every few years to keep it full."},"red-flowering-currant":{"difficulty":1,"sun":"Full sun to part shade","spacing":"4 to 6 feet apart","depth":"Same depth as in the pot","plantText":"red-flowering currant shrubs","firstHarvest":"Blooms from late winter to early spring, starting the year after planting","harvest":"Grown for its flowers rather than fruit. The small blue-black berries are edible but bland; birds love them.","problem":"Few pests. Powdery mildew can appear in shade; plant in sun with good airflow.","varieties":["King Edward VII (deep red)","Pulborough Scarlet","White Icicle (white)"],"care":"Water through the first two summers, then occasionally in drought. Prune right after flowering, cutting a few old stems to the base."},"serviceberry":{"difficulty":1,"sun":"Full sun to part shade","spacing":"6 to 10 feet apart","depth":"Same depth as in the pot or nursery","plantText":"serviceberry shrubs","firstHarvest":"First berries in two to four years","harvest":"Pick in June or July when berries turn dark purple-blue and taste sweet. Net the shrub if you want to beat the birds.","problem":"Rust and leaf spot in wet springs, and birds at harvest. Both are usually minor.","varieties":["Western serviceberry (Amelanchier alnifolia)","Regent (compact)","Smoky (sweet fruit)"],"care":"Water through the first two summers. Prune out a few old stems in late winter to keep it productive, or train it to a single trunk as a small tree."},"camas":{"difficulty":1,"sun":"Full sun to light shade","spacing":"4 to 6 inches apart in groups","depth":"4 inches deep, pointed end up","firstHarvest":"Blooms in April and May","harvest":"Enjoy the flowers in the garden; they make short-lived cut flowers. Let leaves yellow before cutting them back, and let a few seed heads ripen so they spread.","problem":"Few problems. Don't confuse camas with death camas (white or cream flowers), which is poisonous; never eat wild bulbs.","varieties":["Common camas (Camassia quamash)","Great camas (Camassia leichtlinii)","Blue Danube"],"frost":"Fully hardy; needs winter cold to bloom"},"lavender":{"difficulty":1,"sun":"Full sun","spacing":"18 to 36 inches apart, depending on variety","depth":"Plant at the depth it grew in the nursery pot","plantText":"lavender plants","firstHarvest":"Light blooms the first summer; full harvests from year two","harvest":"For drying, cut stems when the lowest flowers on each spike have just opened. Hang small bunches upside down in a dark, airy place.","problem":"Root rot in wet winter soil, which kills more lavender here than cold does. Plant on a mound or slope with gravelly soil, and never mulch with bark around the crown.","varieties":["Hidcote (English, compact)","Munstead (English)","Grosso (lavandin, tall, very fragrant)"],"care":"Water through the first summer only. After flowering, cut plants back by about a third, but never into bare, leafless wood, which won't regrow.","frost":"English types handle about −10°F in well-drained soil"},"tomatillos":{"difficulty":1,"sun":"Full sun","spacing":"3 feet apart","depth":"Bury the stem up to the first leaves, like tomatoes","harvest":"Pick when the fruit fills and starts to split its papery husk. Stored in their husks in the fridge, they keep for two weeks or more.","problem":"A single plant often sets no fruit because tomatillos can't pollinate themselves. Grow at least two.","varieties":["Toma Verde","Grande Rio Verde","Purple"]},"zinnias":{"difficulty":1,"sun":"Full sun","spacing":"9 to 12 inches apart","depth":"¼ inch deep","firstHarvest":"Blooms about 60 to 75 days after sowing","harvest":"Cut when stems are stiff right below the flower (give it a gentle wiggle test). Cut long stems often; the more you cut, the more they bloom.","problem":"Powdery mildew in late summer, especially west of the Cascades. Space plants for airflow and water the soil, not the leaves.","varieties":["Benary's Giant","Queen Lime","Zahara (mildew-resistant)"]},"collards":{"difficulty":1,"sun":"Full sun to part shade","spacing":"18 to 24 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Pick the lower leaves when they're about the size of your hand, and let the top keep growing. Leaves picked after a frost taste sweetest.","problem":"Cabbage worms and aphids, the same pests as kale. Row cover or insect netting keeps the white cabbage moths from laying eggs.","varieties":["Champion","Georgia Southern","Vates","Flash"]},"parsnips":{"difficulty":2,"sun":"Full sun","spacing":"Thin to 3 to 4 inches apart","depth":"½ inch deep","harvest":"Dig roots from late fall through winter, after a few frosts have sweetened them. West of the Cascades they can stay in the ground until early spring.","problem":"Poor sprouting. Parsnip seed loses its punch within a year, and it takes two to four weeks to come up. Use fresh seed and keep the bed moist the whole time.","varieties":["Hollow Crown","Harris Model","Gladiator"]},"celery":{"difficulty":3,"sun":"Full sun; light afternoon shade east of the Cascades","spacing":"10 to 12 inches apart","depth":"Plant starts at the depth they grew in the pot","harvest":"Cut outer stalks as you need them, or cut the whole plant at soil level once the stalks are full-sized, usually from late summer into fall.","problem":"Bolting and stringy stalks. Cold nights right after planting make it go to seed, and dry spells make it tough and bitter. Plant after nights warm up and water deeply every week.","varieties":["Tango","Utah 52-70","Ventura","Golden Self-Blanching"]},"ground-cherries":{"difficulty":1,"sun":"Full sun","spacing":"2 to 3 feet apart","depth":"Bury the stem up to the first leaves, like tomatoes","harvest":"Gather the fruit after it drops to the ground in its husk, when the husk is dry and tan and the fruit inside is golden. Rake or shake the plants every few days.","problem":"Flea beetles chew small holes in young leaves. Row cover until the plants are well grown solves it.","varieties":["Aunt Molly's","Goldie","Cossack Pineapple"]},"sweet-potatoes":{"difficulty":3,"sun":"Full sun; the hottest spot you have","spacing":"12 to 18 inches apart in a raised row","depth":"Bury slips up to the top few leaves","plantText":"sweet potato slips","harvest":"Dig before soil temperatures drop below about 55°F in early fall, and before frost. Cure the roots somewhere warm and humid for a week or two, then store them at room temperature, never in the fridge.","problem":"Cool soil and short summers west of the Cascades. Lay black plastic a week before planting to warm the soil, and choose a short-season variety.","varieties":["Georgia Jet (short season)","Covington","Beauregard","Murasaki"],"care":"Water well for the first two weeks, then only in dry spells: too much water and fertilizer grow vines instead of roots. Black plastic mulch keeps the soil warm all summer."},"pumpkins":{"difficulty":2,"sun":"Full sun","spacing":"4 to 6 feet apart in hills; giant types need 15 feet or more","depth":"1 inch deep","harvest":"Cut pumpkins when the rind is fully colored and too hard to dent with a fingernail, leaving 3 to 4 inches of stem. Bring them in before a hard frost.","problem":"Powdery mildew coats leaves in late summer. Plant resistant varieties and give vines room for airflow.","varieties":["Howden (carving)","Small Sugar (pie)","Jack Be Little (mini)","Atlantic Giant"]},"honeyberries":{"difficulty":1,"sun":"Full sun; part shade east of the Cascades","spacing":"4 to 5 feet apart","depth":"Same depth as in the pot","plantText":"honeyberry bushes","firstHarvest":"A few berries in year two or three; good crops by year four or five","harvest":"Wait until the berries are purple-blue inside as well as outside, about a week after they turn blue. Taste first: underripe ones are sour.","problem":"Birds find the berries the moment they color. Net the bushes in late spring.","varieties":["Aurora","Borealis","Boreal Blizzard","Indigo Gem"],"care":"Plant two compatible varieties that bloom together. Mulch well and water through the first two summers; after that they need very little."},"currants":{"difficulty":1,"sun":"Full sun west of the Cascades; afternoon shade east","spacing":"4 to 5 feet apart","depth":"An inch or two deeper than in the pot","plantText":"currant bushes","firstHarvest":"A small crop in year two; full crops from year three","harvest":"Pick whole clusters (strigs) once all the berries are colored. Red currants hang on the bush for a couple of weeks; black currants are best picked as soon as they're ripe.","problem":"Imported currantworm, a sawfly larva that strips leaves in spring. Check under the lower leaves in April and May and pick them off.","varieties":["Rovada (red)","Red Lake (red)","Blanka (white)","Titania (black, rust-resistant)"],"care":"Prune in late winter: keep about ten stems of different ages and cut out any older than three or four years. Mulch to keep roots cool."},"gooseberries":{"difficulty":1,"sun":"Full sun to part shade","spacing":"4 to 5 feet apart","depth":"An inch or two deeper than in the pot","plantText":"gooseberry bushes","firstHarvest":"A small crop in year two; full crops from year three","harvest":"Pick green for cooking when the berries are full-sized but firm, or leave them a few weeks to soften and sweeten for eating fresh.","problem":"Powdery mildew and imported currantworm. Choose mildew-resistant varieties, prune for airflow and check the leaves in spring.","varieties":["Invicta","Hinnonmaki Red","Pixwell","Captivator (nearly thornless)"],"care":"Prune in late winter to open the center of the bush and remove stems older than three years. Thick gloves help."},"elderberries":{"difficulty":1,"sun":"Full sun to part shade","spacing":"6 to 8 feet apart","depth":"Same depth as in the pot","plantText":"elderberry shrubs","firstHarvest":"Some berries in year two; full crops from year three","harvest":"Cut whole clusters when nearly all the berries are dark and soft. Strip the berries off the stems and cook them before eating.","problem":"Birds, and toxic parts. Leaves, stems and unripe berries contain compounds that can make you sick, so remove every bit of stem and always cook the berries.","varieties":["Blue elderberry (native)","York","Adams","Nova"],"care":"Plant two varieties for better crops. Water through the first summer, and cut out old, weak canes in late winter to keep the shrub productive."},"peonies":{"difficulty":1,"sun":"Full sun; at least six hours","spacing":"3 feet apart","depth":"Eyes (buds) 1 to 2 inches below the soil, no deeper","firstHarvest":"Usually blooms in the second or third spring","harvest":"Cut when buds feel soft like a marshmallow and show color. Leave at least a third of the stems on the plant so it can rebuild for next year.","problem":"Botrytis (gray mold) blackens buds and stems in wet springs. Cut all stems to the ground in fall and throw them out rather than composting.","varieties":["Sarah Bernhardt","Festiva Maxima","Coral Charm","Bartzella (Itoh)"],"frost":"Fully hardy; needs winter cold to bloom"},"mustard-greens":{"difficulty":1,"sun":"Full sun to part shade","spacing":"Thin to 6 to 12 inches apart","depth":"¼ to ½ inch deep","harvest":"Pick baby leaves about three weeks after sowing, or cut outer leaves from full-size plants. Leaves picked after a frost are milder.","problem":"Flea beetles riddle young leaves with tiny holes in spring, and slugs chew them in wet weather. Row cover laid on at sowing keeps the beetles off.","varieties":["Red Giant","Green Wave","Mizuna"]},"mache":{"difficulty":1,"sun":"Full sun to part shade","spacing":"Thin to 3 to 4 inches apart","depth":"¼ to ½ inch deep","harvest":"Cut whole rosettes at the soil line once they have 8 to 10 leaves, or pick the larger ones and leave the rest to grow. Rinse well, since grit hides in the rosettes.","problem":"Slow, patchy sprouting in warm soil; the seed germinates best once late-summer soil cools. Keep the seedbed moist, and watch for slugs in winter.","varieties":["Vit","Verte de Cambrai","Large Seeded Dutch"],"frost":"Very hardy; picks through most winters"},"radicchio":{"difficulty":2,"sun":"Full sun","spacing":"8 to 12 inches apart","depth":"¼ inch deep","harvest":"Cut heads at the base when they feel firm, usually in fall. Leaves stay green and loose in summer heat; the red color and tight heads come with cool nights.","problem":"Bolting from spring sowings, and slugs hiding in the heads in fall. Sow in midsummer for fall heads, and pick by variety: modern hybrids head up more reliably.","varieties":["Palla Rossa","Rossa di Treviso","Indigo"],"frost":"Handles light frost; heads sweeten in cold weather"},"sorrel":{"difficulty":1,"sun":"Full sun to part shade","spacing":"Thin to 12 inches apart","depth":"½ inch deep","harvest":"Pick young leaves from early spring on; they're the most tender and least sour. Cut the plant back hard in midsummer for a fresh flush of leaves in fall.","problem":"Flower stalks in late spring make the leaves tough. Cut them off at the base as soon as they appear. Slugs and aphids are occasional pests.","varieties":["French sorrel","Garden sorrel (Large de Belleville)","Red-veined sorrel"],"frost":"Hardy perennial; often the first green of spring"},"horseradish":{"difficulty":1,"sun":"Full sun to light shade","spacing":"18 to 24 inches apart","depth":"Lay root cuttings at a slant, top end 2 to 3 inches below the soil","plantText":"horseradish root cuttings","firstHarvest":"Dig roots from the first fall on","harvest":"Dig roots in fall after a frost, when the flavor is strongest, or any time through winter. Grate them fresh; the heat fades within minutes of grating.","problem":"It spreads. Any piece of root left in the ground sprouts, so grow it in a large tub or a corner you'll never want back, and dig carefully.","varieties":["Maliner Kren (Bohemian)","Big Top Western","Common horseradish"],"care":"Water in dry spells so the roots stay tender. Remove side roots in summer if you want one thick, straight main root.","frost":"Very hardy; roots survive any Northwest winter"},"sage":{"difficulty":1,"sun":"Full sun","spacing":"18 to 24 inches apart","depth":"Plant at the depth it grew in the nursery pot","plantText":"young sage plants","firstHarvest":"Pick lightly the first year, freely after that","harvest":"Pick leaves any time; flavor is strongest just before the plant flowers in early summer. Leave plenty of leaves on young plants going into winter.","problem":"Root rot in soggy winter soil, and plants that turn woody and sparse after a few years. Plant on a mound or in a pot, and replace old plants every four or five years.","varieties":["Common sage","Berggarten (broad leaves, rarely flowers)","Purple sage"],"care":"Water through the first summer, then only in long dry spells. Cut back by about a third in spring once new growth starts, but never into bare wood.","frost":"Very hardy in well-drained soil; purple and golden types less so"},"lemon-balm":{"difficulty":1,"sun":"Full sun to part shade","spacing":"18 to 24 inches apart","depth":"Plant at the depth it grew in the nursery pot","plantText":"young lemon balm plants","firstHarvest":"Pick from the first summer","harvest":"Cut stems before flowering for the strongest lemon scent. Use leaves fresh in tea, or dry them quickly in the shade, since they lose scent slowly in damp air.","problem":"It seeds itself all over the garden. Shear the plants back before the small white flowers set seed, which also brings a fresh crop of leaves.","varieties":["Common lemon balm","Aurea (gold-variegated)","Lime balm"],"care":"It tolerates most soils and some shade. Cut the whole plant back by half in midsummer to keep it bushy and stop it seeding.","frost":"Hardy perennial; dies back and regrows each spring"},"tarragon":{"difficulty":2,"sun":"Full sun; tolerates light afternoon shade","spacing":"18 to 24 inches apart","depth":"Plant at the depth it grew in the nursery pot","plantText":"young French tarragon plants","firstHarvest":"Pick lightly the first year, freely after that","harvest":"Snip sprigs from late spring through summer. The flavor is best fresh or frozen; dried tarragon loses most of its anise taste.","problem":"Root rot in wet winter soil, and fading flavor as clumps age. Plant where water drains away fast, and divide clumps every three years in spring.","varieties":["French tarragon","Russian tarragon (weak flavor)","Mexican tarragon (a frost-tender substitute)"],"care":"Water through the first summer, then sparingly. Cut stems to the ground in late fall and mulch lightly in cold eastern gardens.","frost":"Very hardy in well-drained soil; dies back each winter"},"cosmos":{"difficulty":1,"sun":"Full sun","spacing":"12 inches apart","depth":"¼ inch deep","firstHarvest":"Blooms about 60 to 80 days after sowing","harvest":"Cut when the first petals are just opening; buds that show color open in the vase. Cut often and deadhead to keep plants flowering until frost.","problem":"Tall plants flop after rain and wind. Pinch young plants once to make them bushier, and stake or net the tall varieties.","varieties":["Sensation Mix","Double Click","Sonata (dwarf)"]},"nasturtiums":{"difficulty":1,"sun":"Full sun to part shade","spacing":"10 to 12 inches apart","depth":"½ to 1 inch deep","firstHarvest":"Blooms about 50 to 60 days after sowing","harvest":"Pick flowers and young leaves any time for salads; both taste peppery. Pick the green seed pods to pickle, or let them dry and save them to sow next year.","problem":"Black aphids cluster under the leaves in summer. Hose them off or pick off the worst leaves. Rich soil and fertilizer give lots of leaves and few flowers.","varieties":["Alaska (variegated leaves)","Empress of India","Jewel Mix"]},"marigolds":{"difficulty":1,"sun":"Full sun","spacing":"8 to 12 inches apart (French); 12 to 18 inches (African)","depth":"¼ inch deep","firstHarvest":"Blooms about 50 to 60 days after sowing","harvest":"Deadhead spent flowers to keep new ones coming. For cutting, pick when blooms are fully open; they last about a week in water.","problem":"Slugs eat young plants overnight in damp spring weather, and gray mold rots big African blooms in late-summer rain. Plant out once the soil warms, and give plants airflow.","varieties":["Durango (French)","Crackerjack (African)","Lemon Gem (signet)"]},"calendula":{"difficulty":1,"sun":"Full sun to light shade","spacing":"10 to 12 inches apart","depth":"¼ to ½ inch deep","firstHarvest":"Blooms about 45 to 60 days after sowing","harvest":"Pick flowers when fully open, every few days, to keep plants blooming. Pull the petals for salads, or dry whole flowers on a screen.","problem":"Powdery mildew on the leaves in late summer. It rarely stops the flowers; pull tired plants and let a fresh fall sowing take over.","varieties":["Resina","Zeolights","Pacific Beauty"]},"ranunculus":{"difficulty":3,"sun":"Full sun","spacing":"6 to 9 inches apart","depth":"2 inches deep, claws pointing down","plantText":"soaked ranunculus corms","firstHarvest":"Blooms about 90 days after planting","harvest":"Cut when the buds are colored and soft like a marshmallow but not yet open. They last a week or more in the vase.","problem":"Corms rot in cold, soggy soil, and young plants are damaged below about 25°F. Plant in raised beds that drain well, and cover with frost cloth on cold nights.","varieties":["Tecolote mix","Amandine series","La Belle series"],"care":"Soak corms in room-temperature water for three to four hours first. After planting, water once and then only when the top inch is dry until leaves appear.","frost":"Leaves handle light frost; cover below about 25°F"},"snapdragons":{"difficulty":2,"sun":"Full sun","spacing":"9 to 12 inches apart","depth":"Press seeds onto the soil surface; they need light to sprout","firstHarvest":"Blooms about 75 to 100 days after sowing","harvest":"Cut stems when the bottom third of the flowers are open. Pinch young plants once for more, shorter stems, or leave them for one tall spike.","problem":"Rust (orange spots under the leaves) in damp weather. Water at the soil, give plants space, and pull infected plants rather than composting them.","varieties":["Rocket series (tall)","Madame Butterfly (double flowers)","Chantilly (open-faced)"],"frost":"Handles light frost; often overwinters on the west side"},"persimmons":{"difficulty":2,"sun":"Full sun; the warmest spot you have","spacing":"15 to 20 feet apart","depth":"Same depth as in the pot or nursery","plantText":"persimmon trees","firstHarvest":"First fruit in three to five years","harvest":"Pick non-astringent types like Fuyu when fully orange; they're crisp and sweet right away. Astringent types like Hachiya must soften to jelly before eating. Clip fruit with a short stem.","problem":"Fruit drop and slow ripening in cool summers. Most young trees also have a long taproot and settle in slowly, so plant small trees and water well through the first summers.","varieties":["Fuyu (non-astringent)","Saijo (astringent, hardy)","Hachiya (astringent)"],"care":"Water deeply every week or two through the first two summers. Prune lightly in late winter for shape; heavy pruning cuts the crop.","frost":"Asian types hardy to about 0°F once established"},"asian-pears":{"difficulty":2,"sun":"Full sun","spacing":"12 to 15 feet apart (semi-dwarf)","depth":"Graft union 2 to 3 inches above the soil","plantText":"Asian pear trees","firstHarvest":"First fruit in three to five years","harvest":"Unlike European pears, Asian pears ripen on the tree. Pick when the skin turns yellow or golden-brown and the fruit tastes sweet; they keep for weeks in the fridge.","problem":"Overcropping and fire blight. Thin young fruit to one per cluster about six inches apart, and cut out blackened shoots well below the damage on a dry day.","varieties":["Shinseiki","Chojuro","Hosui"],"care":"Water deeply through the first two summers. Plant a second variety that blooms at the same time unless a neighbor grows one.","frost":"Very hardy once dormant; blossoms can be hit by late frost"},"quince":{"difficulty":2,"sun":"Full sun","spacing":"12 to 15 feet apart","depth":"Same depth as in the pot or nursery","plantText":"quince trees","firstHarvest":"First fruit in three to five years","harvest":"Pick in October when the fruit turns from green to fully yellow and smells strongly fragrant. Handle gently; they bruise easily. Cook them into jelly, paste or poached fruit.","problem":"Quince leaf blight causes brown leaf spots and early leaf drop in wet springs, and fire blight can blacken shoots. Rake up fallen leaves and prune for good airflow.","varieties":["Aromatnaya","Smyrna","Orange"],"care":"Water deeply through the first two summers. Prune lightly in late winter to open up the center.","frost":"Very hardy; blooms late enough to miss most frosts"},"mulberries":{"difficulty":1,"sun":"Full sun","spacing":"15 to 30 feet apart, depending on variety","depth":"Same depth as in the pot or nursery","plantText":"mulberry trees","firstHarvest":"First fruit in two to three years","harvest":"Ripe berries drop at a touch. Spread a sheet under the branches and shake gently. The harvest lasts several weeks in summer.","problem":"Birds, and stains. Birds share the crop, and dropped fruit stains paving, cars and shoes, so site the tree over lawn or mulch.","varieties":["Illinois Everbearing","Gerardi Dwarf","Pakistan (milder areas)"],"care":"Water deeply through the first two summers. Prune in late winter to keep the tree a size you can pick and net.","frost":"Most are very hardy; Pakistan types need mild winters"},"thimbleberry":{"difficulty":1,"sun":"Part shade to full sun","spacing":"3 to 4 feet apart","depth":"Same depth as in the pot or nursery","plantText":"potted thimbleberry","firstHarvest":"Berries the second summer","harvest":"Pick in midsummer when the berries are deep red and slip off the core easily. They're soft and crumbly, so eat them fresh or make jam the same day.","problem":"It spreads by underground stems. Give it room, or mow or pull suckers that stray out of bounds.","varieties":["Thimbleberry (Rubus parviflorus)"],"care":"Water through the first summer. In late winter, cut canes that fruited to the ground, as with raspberries."},"salmonberry":{"difficulty":1,"sun":"Part shade to full sun","spacing":"4 to 6 feet apart","depth":"Same depth as in the pot or nursery","plantText":"salmonberry shrubs","firstHarvest":"Berries in the second or third year","harvest":"Pick in late spring and early summer when berries are fully colored, from gold to deep red, and pull free easily. They're juicy and mild; eat them fresh.","problem":"Prickly canes that spread by roots into thickets. Plant where that's welcome, and cut out old canes to keep it open.","varieties":["Salmonberry (Rubus spectabilis)","Olympic Double (double flowers)"],"care":"Water through the first two summers. Cut a few of the oldest canes to the ground each winter."},"salal":{"difficulty":2,"sun":"Part shade; full sun on the coast","spacing":"2 to 3 feet apart","depth":"Same depth as in the pot or nursery","plantText":"potted salal","firstHarvest":"Berries after two to three years","harvest":"Pick the dark purple berries in late summer when they're soft. They're mild and seedy; mix them with other berries for jam.","problem":"Slow to settle in. Small plants can sit still for a year or two before they spread, and they struggle in heavy clay or alkaline soil.","varieties":["Salal (Gaultheria shallon)"],"care":"Water through the first two summers and mulch with leaves or bark. No fertilizer needed."},"kinnikinnick":{"difficulty":2,"sun":"Full sun to light shade","spacing":"12 to 24 inches apart","depth":"Same depth as in the pot; don't bury the stems","plantText":"potted kinnikinnick","firstHarvest":"Flowers in spring, berries in fall","harvest":"Enjoy the berries as winter bird food. They're edible but dry and mealy, so most people leave them.","problem":"Slow to fill in, and root rot in heavy, wet soil. Mulch with gravel or bark between plants to hold back weeds while they spread.","varieties":["Vancouver Jade","Massachusetts","Wood's Compact"],"care":"Water through the first summer, then only in long droughts. Weed carefully until the mat closes.","frost":"Very hardy; evergreen through winter"},"western-columbine":{"difficulty":1,"sun":"Full sun to part shade","spacing":"12 to 18 inches apart","depth":"Same depth as in the pot; scatter seeds on the surface","plantText":"western columbine plants","firstHarvest":"Blooms the first or second spring","harvest":"Enjoy the flowers in the garden from late spring into summer. Let some seed pods ripen and split so seedlings replace older plants.","problem":"Leaf miners draw white squiggles in the leaves. It's cosmetic; cut the foliage back after flowering and fresh leaves grow.","varieties":["Western columbine (Aquilegia formosa)"],"care":"Water through the first summer. Plant away from garden hybrid columbines if you want seedlings to stay true."},"douglas-aster":{"difficulty":1,"sun":"Full sun to part shade","spacing":"18 to 24 inches apart","depth":"Same depth as in the pot or nursery","plantText":"Douglas aster plants","firstHarvest":"Blooms from mid to late summer","harvest":"Enjoy the flowers in the garden through late summer and fall. Leave the seed heads for finches and cut stems back in late winter.","problem":"Powdery mildew in dry late summers, and spreading by underground stems. Water in long dry spells, and dig out runners where you don't want them.","varieties":["Douglas aster (Symphyotrichum subspicatum)"],"care":"Water through the first summer. Cut stems back by a third in early June for bushier plants that don't flop."},"oregon-sunshine":{"difficulty":1,"sun":"Full sun","spacing":"12 to 18 inches apart","depth":"Same depth as in the pot; press seeds onto the surface in fall","plantText":"Oregon sunshine plants","firstHarvest":"Blooms in late spring and early summer","harvest":"Enjoy the flowers in the garden. Shear plants lightly after bloom to keep them tidy and compact.","problem":"Root rot in rich soil, wet beds or with summer watering. Plant it with other dry-garden plants and leave it alone.","varieties":["Oregon sunshine (Eriophyllum lanatum)"],"care":"Water only during the first summer. Plants are short-lived but reseed in open, gravelly ground."},"pacific-ninebark":{"difficulty":1,"sun":"Full sun to part shade","spacing":"6 to 8 feet apart","depth":"Same depth as in the pot or nursery","plantText":"Pacific ninebark shrubs","firstHarvest":"Blooms from the second spring","harvest":"Enjoy the flower clusters in late spring and the reddish seed heads in summer, which birds pick through.","problem":"Powdery mildew in dry spots, and size: it can reach 10 feet tall. Give it moist soil and space.","varieties":["Pacific ninebark (Physocarpus capitatus)","Mallow ninebark (P. malvaceus, east side)"],"care":"Water through the first two summers. Cut a few of the oldest stems to the ground in late winter to keep it full."},"sword-fern":{"difficulty":1,"sun":"Part to full shade","spacing":"2 to 3 feet apart","depth":"Crown at soil level; don't bury it","plantText":"sword ferns","firstHarvest":"Evergreen fronds all year","harvest":"Enjoy the evergreen fronds all year. Cut off old, tattered fronds in early spring, just before the new fiddleheads unroll.","problem":"Drought stress. Ferns in sun or dry soil brown at the tips and decline in hot summers. Keep them in shade, mulch with leaves and water deeply in long dry spells.","varieties":["Western sword fern (Polystichum munitum)"],"care":"Water through the first two summers. Leave fallen leaves around the crowns as mulch."},"oregon-iris":{"difficulty":1,"sun":"Full sun to light shade","spacing":"12 to 18 inches apart","depth":"Same depth as in the pot; rhizomes just below the soil","plantText":"Oregon iris plants","firstHarvest":"Blooms in late spring","harvest":"Enjoy the flowers in late spring. Leave the leaves standing through summer; trim old ones in late winter.","problem":"Moving it. Established clumps sulk or die when dug in spring or summer. Divide only in fall, after the rains start.","varieties":["Oregon iris (Iris tenax)","Pacific Coast hybrid irises"],"care":"Water through the first summer only. It needs no fertilizer."}}};
